public enum class Axis { HORIZONTAL, VERTICAL }

public data class Insets(val left: Double, val top: Double, val right: Double, val bottom: Double)

public data class Size(val width: Double, val height: Double)

/** Picks a label's wording from what is typed; null keeps the label's text. Table resolvers become maps. */
public typealias PlateLabelResolver = (group: (String) -> String) -> String?

/** The spec a plate should become for its values (null keeps it); PlateController follows it. */
public typealias PlateSpecResolver = (group: (String) -> String) -> PlateSpec?

/** Picks a theme from what is typed. */
public typealias PlateThemeResolver = (base: PlateTheme, group: (String) -> String) -> PlateTheme

/** One editable position on a plate. [box].height doubles as the glyph height. */
public class PlateSlot(
    public val alphabet: PlateAlphabet,
    public val box: PlateBox,
    /** Ink for this slot, or null for the theme's. */
    public val color: Color? = null,
    public val length: Int = 1,
    minLength: Int? = null,
    public val spacing: Double = 0.0,
) {
    public val minLength: Int = minLength ?: length

    init {
        require(length >= 1) { "A slot holds at least one character." }
        require(this.minLength in 1..length) { "minLength is 1..length." }
    }

    /** Legal, possibly partial, content; a chosen symbol is judged whole. */
    public fun accepts(value: String): Boolean {
        if (alphabet.input == AlphabetInput.CHOSEN) return alphabet.accepts(value)
        val characters = splitRunes(value)
        return characters.isNotEmpty() && characters.size <= length && characters.all(alphabet::accepts)
    }

    public fun canonical(value: String): String = alphabet.canonicalAll(value)

    public fun render(value: String): String = alphabet.renderAll(value)

    public fun isFull(value: String?): Boolean = value != null && splitRunes(value).size >= length

    public fun isComplete(value: String?): Boolean = value != null && splitRunes(value).size >= minLength
}

/** An echo of a slot's value painted elsewhere; owns no position in [PlateSpec.slots]. */
public class PlateMirror(
    public val source: Int,
    public val box: PlateBox,
    public val glyphHeight: Double,
    public val alphabet: PlateAlphabet? = null,
    public val editable: Boolean = false,
)

public class PlateRule(public val box: PlateBox)

/** The theme's field colour airbrushed over a stripes leaf. */
public data class PlateFog(val center: Point, val radii: Size, val opacity: Double = 1.0, val plateau: Double = 0.5)

/** What a [PlateSection] leaf is painted in; the three objects resolve at render time. */
public sealed interface PlateFill {
    public data class ColorFill(val color: Color) : PlateFill

    /** Parallel bands tilted by [angle] radians; [stops] has one fewer entry than [stripes]. */
    public data class StripesFill(
        val stripes: List<PlateFill>, val stops: List<Double>, val angle: Double = 0.0, val fog: PlateFog? = null,
    ) : PlateFill

    public object Field : PlateFill
    public object Panel : PlateFill
    public object Divider : PlateFill
}

public val PlateFill.paintsPanel: Boolean
    get() = this is PlateFill.Panel || (this is PlateFill.StripesFill && stripes.any { it is PlateFill.Panel })

/** The paint colour; not meaningful for stripes, paint each stripe. */
public fun PlateFill.resolve(field: Color, panel: Color, divider: Color): Color = when (this) {
    is PlateFill.ColorFill -> color
    is PlateFill.StripesFill -> error("paint each stripe")
    PlateFill.Field -> field
    PlateFill.Panel -> panel
    PlateFill.Divider -> divider
}

/** One region of a split; [end] is its far edge along the parent's axis, null on the last part. */
public class PlatePart(public val section: PlateSection, public val end: Double? = null, public val divider: Double = 0.0)

public class SectionLayout(public val leaves: List<Pair<PlateSection, Rect>>, public val dividers: List<Rect>)

/** A guillotine tree of columns and rows whose leaves are fills. */
public sealed interface PlateSection {
    /** [shape] is an SVG path in leaf-local units. */
    public class Leaf(public val fill: PlateFill, public val shape: String? = null) : PlateSection

    public class Split(public val axis: Axis, public val parts: List<PlatePart>) : PlateSection

    public val paintsPanel: Boolean
        get() = when (this) {
            is Leaf -> fill.paintsPanel
            is Split -> parts.any { it.section.paintsPanel }
        }

    /** The leaves and dividers of this tree laid over [bounds], depth-first. */
    public fun layout(bounds: Rect): SectionLayout {
        val leaves = mutableListOf<Pair<PlateSection, Rect>>()
        val dividers = mutableListOf<Rect>()
        fun walk(s: PlateSection, r: Rect) {
            if (s is Leaf) {
                leaves.add(s to r)
                return
            }
            s as Split
            val across = s.axis == Axis.HORIZONTAL
            var start = if (across) r.left else r.top
            val last = s.parts.size - 1
            for ((i, part) in s.parts.withIndex()) {
                val end = if (i == last) (if (across) r.right else r.bottom) else part.end!!
                walk(
                    part.section,
                    if (across) Rect.fromLTRB(start, r.top, end, r.bottom) else Rect.fromLTRB(r.left, start, r.right, end),
                )
                if (part.divider > 0 && i != last) {
                    val half = part.divider / 2
                    dividers.add(
                        if (across) Rect.fromLTRB(end - half, r.top, end + half, r.bottom)
                        else Rect.fromLTRB(r.left, end - half, r.right, end + half),
                    )
                }
                start = end
            }
        }
        walk(this, bounds)
        return SectionLayout(leaves, dividers)
    }

    public companion object {
        public val plain: PlateSection = Leaf(PlateFill.Field)
    }
}

