public class PlateTextGroup(public val indices: List<Int>, public val prefix: String = "", public val key: String? = null)

/** A complete plate design. Equal iff the ids match. */
public class PlateSpec(
    public val id: String,
    public val country: PlateCountry,
    public val canvasWidth: Double,
    public val canvasHeight: Double,
    public val panel: PlatePanel?,
    public val slots: List<PlateSlot>,
    public val background: PlateSection = PlateSection.plain,
    public val bands: List<PlateBand> = emptyList(),
    public val rules: List<PlateRule> = emptyList(),
    public val labels: List<PlateLabel> = emptyList(),
    public val decals: List<PlateDecal> = emptyList(),
    public val mirrors: List<PlateMirror> = emptyList(),
    public val textDirection: TextDirection = TextDirection.LTR,
    public val borderWidthRatioOverride: Double? = null,
    public val inkOverride: Color? = null,
    public val textGroups: List<PlateTextGroup> = emptyList(),
    public val restrictions: List<PlateRestriction> = emptyList(),
    public val resolveTheme: PlateThemeResolver? = null,
    public val resolveRegion: PlateLabelResolver? = null,
    public val resolveSpec: PlateSpecResolver? = null,
) {
    public val slotCount: Int get() = slots.size

    public fun slotAt(index: Int): PlateSlot? = slots.getOrNull(index)

    /** [textGroups], or one group per slot when none are declared. */
    public val effectiveTextGroups: List<PlateTextGroup>
        get() = textGroups.ifEmpty { slots.indices.map { PlateTextGroup(listOf(it)) } }

    public fun groupAt(index: Int): PlateTextGroup? = effectiveTextGroups.firstOrNull { index in it.indices }

    public fun groupNamed(key: String): PlateTextGroup? = effectiveTextGroups.firstOrNull { it.key == key }

    public fun renderGroup(group: PlateTextGroup, values: List<String?>): String = buildString {
        append(group.prefix)
        for (i in group.indices) append(slotAt(i)?.render(if (i < values.size) values[i] ?: "" else "") ?: "")
    }

    public fun nextIndex(index: Int): Int? = if (index >= 0 && index + 1 < slots.size) index + 1 else null

    public fun previousIndex(index: Int): Int? = if (index > 0 && index < slots.size) index - 1 else null

    public fun indicesOfGroup(key: String): List<Int> = groupNamed(key)?.indices ?: emptyList()

    /** The raw values of the group named [key], concatenated. */
    public fun valueOfGroup(key: String, values: List<String?>): String =
        indicesOfGroup(key).filter { it < values.size }.joinToString("") { values[it] ?: "" }

    public fun restrictionViolatedBy(values: List<String?>): PlateRestriction? =
        restrictions.firstOrNull { it.matches(valueOfGroup(it.group, values)) }

    public fun checkRestrictions(values: List<String?>) {
        restrictionViolatedBy(values)?.let { throw PlateRestrictionException(it) }
    }

    override fun equals(other: Any?): Boolean = other is PlateSpec && other.id == id

    override fun hashCode(): Int = id.hashCode()
}
